import React from "react";
import { Audio, interpolate, Sequence, staticFile, useVideoConfig } from "remotion";
import { Word } from "./timing";

// Generated by scripts/sfx.py — add new names there first.
export type SfxName =
  | "whoosh"
  | "whoosh_fast"
  | "tick"
  | "pop"
  | "impact"
  | "thud"
  | "riser"
  | "glitch"
  | "chime"
  | "swell"
  | "beep";
export type MusicName = "tension" | "wonder" | "dark";

const SFX_FRAMES: Record<SfxName, number> = {
  whoosh: 30,
  whoosh_fast: 15,
  tick: 4,
  pop: 6,
  impact: 70,
  thud: 18,
  riser: 62,
  glitch: 12,
  chime: 75,
  swell: 50,
  beep: 6,
};

/**
 * One sound effect at a frame. `lead` starts it early so the sound peaks on the cue
 * (risers end on the hit, whooshes peak mid-move).
 */
export const Sfx: React.FC<{ at: number; name: SfxName; volume?: number; lead?: number }> = ({ at, name, volume = 0.7, lead }) => {
  const defaultLead = name === "riser" ? 58 : name === "whoosh" ? 10 : name === "swell" ? 45 : 0;
  const from = Math.max(0, at - (lead ?? defaultLead));
  return (
    <Sequence from={from} durationInFrames={SFX_FRAMES[name] + 4} layout="none" name={`sfx:${name}`}>
      <Audio src={staticFile(`sfx/${name}.wav`)} volume={volume} />
    </Sequence>
  );
};

/** Counter ticks: one tick every `every` frames between two frames (pair with StatPill count-ups). */
export const Ticks: React.FC<{ from: number; to: number; every?: number; volume?: number }> = ({ from, to, every = 2, volume = 0.35 }) => (
  <>
    {Array.from({ length: Math.max(0, Math.floor((to - from) / every)) }, (_, i) => (
      <Sfx key={i} at={from + i * every} name="tick" volume={volume * (0.6 + 0.4 * (i / Math.max(1, (to - from) / every)))} />
    ))}
  </>
);

/**
 * Music bed, ducked under the voice: drops to `duck` × volume while words are spoken
 * (smoothed so it breathes, not pumps), fades in/out at the edges.
 */
export const MusicBed: React.FC<{
  name: MusicName;
  words: Word[];
  volume?: number;
  duck?: number;
  startAt?: number;
  /** deliberate silences: [from, to] frame ranges where the music drops out (6-frame fades) */
  cuts?: [number, number][];
}> = ({ name, words, volume = 0.32, duck = 0.45, startAt = 0, cuts = [] }) => {
  const { fps, durationInFrames } = useVideoConfig();
  const speaking = (f: number) => {
    const s = f / fps;
    return words.some((w) => s >= w.start - 0.08 && s <= w.end + 0.25) ? 1 : 0;
  };
  return (
    <Audio
      src={staticFile(`music/${name}.wav`)}
      startFrom={startAt}
      volume={(f) => {
        let sp = 0;
        for (let k = -4; k <= 4; k++) sp += speaking(f + k);
        const d = 1 - (1 - duck) * (sp / 9);
        const edge = interpolate(f, [0, 6, durationInFrames - 10, durationInFrames], [0.6, 1, 1, 0.5], {
          extrapolateLeft: "clamp",
          extrapolateRight: "clamp",
        });
        const cut = cuts.reduce(
          (m, [a, b]) => Math.min(m, interpolate(f, [a - 6, a, b, b + 6], [1, 0, 0, 1], { extrapolateLeft: "clamp", extrapolateRight: "clamp" })),
          1,
        );
        return volume * d * edge * cut;
      }}
    />
  );
};
